<script lang="ts">
 import CalendarPersonPicker from './CalendarPersonPicker.svelte';
 import CalendarPicker,{type CalendarSource} from './CalendarPicker.svelte';
 import {tick} from 'svelte';
 import {meetingConflicts} from './meeting-conflicts';
 import {eventDate} from './calendar';
 import TeamsMeeting from './TeamsMeeting.svelte';
 import MeetingComposer from './MeetingComposer.svelte';
 import MeetingEditor from './MeetingEditor.svelte';
 import {canManageMeeting} from './meeting-edit';
 import MeetingResponse from './MeetingResponse.svelte';
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {openUrl} from '@tauri-apps/plugin-opener';
 import {CalendarDays,ChevronLeft,ChevronRight,RefreshCw,X,Clock,MapPin,Users,LayoutGrid,List} from 'lucide-svelte';
 import {calendarRange,calendarAnchor,validCalendarDay,localDate,eventWhen,eventDay,responseLabel,attendeeResponseLabel,calendarAttendeeLabel,calendarLink,type CalendarEvent} from './calendar';
 let {initialEvent=null,onNavigationHandled=()=>{},ownId,isLive,sidebarOpen,detailsOpen,onDetailsAvailable,onOpenDetails,onCloseDetails,onSignIn}:{initialEvent?:CalendarEvent|null;onNavigationHandled?:()=>void;ownId:string;isLive:boolean;sidebarOpen:boolean;detailsOpen:boolean;onDetailsAvailable:(available:boolean)=>void;onOpenDetails:()=>void;onCloseDetails:()=>void;onSignIn:()=>void}=$props();
 let day=$state(localDate(new Date())),days=$state(7),rows=$state<CalendarEvent[]>([]),selected=$state<CalendarEvent|null>(null),next=$state<string|null>(null),busy=$state(false),error=$state(''),permitted=$state(false),checking=$state(true);
 let sources=$state<CalendarSource[]>([]),sourceNext=$state<string|null>(null),sourceBusy=$state(false),sourceError=$state(''),groupError=$state(''),enabled=$state<string[]>(['primary']),focusId=$state<string|null>(null);
 let extra=$state<Record<string,{rows:CalendarEvent[];next:string|null;busy:boolean;error:string;range:string}>>({});
 let agendaPane=$state<HTMLDivElement>();let focusSnapshot:{day:string;days:number;selected:CalendarEvent|null;scroll:number;details:boolean}|null=null;let sourceSerial=0;const eventRequests:Record<string,number>={};
 const calendarTone=(id?:string)=>!id||id==='primary'?'var(--accent)':`var(--calendar-color-${Array.from(id).reduce((n,c)=>n+c.charCodeAt(0),0)%3+1})`;
 const eventKey=(e:CalendarEvent)=>JSON.stringify([e.calendarId||'primary',e.id]);
 const sourceName=(id?:string)=>!id||id==='primary'?'My calendar':sources.find(s=>s.id===id)?.name||'Calendar';
 const activeSources=$derived(focusId?[focusId]:enabled);
 const visibleRows=$derived([...activeSources.flatMap(id=>id==='primary'?rows:extra[id]?.range===day+'/'+days?extra[id].rows:[])].sort((a,b)=>(eventDate(a.start)?.getTime()??0)-(eventDate(b.start)?.getTime()??0)||eventKey(a).localeCompare(eventKey(b))));
 function savePeople(){try{localStorage.setItem('taut-calendar-people:'+ownId,JSON.stringify(sources.filter(s=>s.kind==='person').map(s=>s.id.slice(7))));}catch{sourceError='Calendar added for this session; this device could not save the list.';}}
 function addPerson(source:CalendarSource){if(!alive||composing||managing)return;sources=[...new Map([...sources,source].map(s=>[s.id,s])).values()];savePeople();}
 function removePerson(id:string){if(focusId||composing||managing)return;sources=sources.filter(s=>s.id!==id);delete extra[id];eventRequests[id]=(eventRequests[id]??0)+1;if(selected?.calendarId===id)selected=null;enabled=enabled.filter(s=>s!==id);try{localStorage.setItem('taut-calendar-view:'+ownId,JSON.stringify(enabled));}catch{}savePeople();}
 let layout=$state<'cards'|'agenda'>('cards');
 const eventDays=$derived.by(()=>{const groups=new Map<string,CalendarEvent[]>();for(const event of visibleRows){const date=eventDay(event);groups.set(date,[...(groups.get(date)??[]),event]);}return [...groups].map(([date,events])=>({date,events}));});
 function dayLabel(date:string){return validCalendarDay(date)?new Date(date+'T12:00:00').toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'}):date;}
 async function changeLayout(value:'cards'|'agenda'){
  if(layout===value)return;
  const pane=agendaPane;const top=pane?.getBoundingClientRect().top??0;
  const anchor=pane?Array.from(pane.querySelectorAll<HTMLElement>('.event')).find(el=>el.getBoundingClientRect().bottom>top):null;
  const key=anchor?.dataset.eventKey,offset=anchor?anchor.getBoundingClientRect().top-top:0;
  layout=value;try{localStorage.setItem('taut-calendar-layout',value);}catch{}
  await tick();if(pane&&key){const target=Array.from(pane.querySelectorAll<HTMLElement>('.event')).find(el=>el.dataset.eventKey===key);if(target)pane.scrollTop+=target.getBoundingClientRect().top-pane.getBoundingClientRect().top-offset;}
 }
 async function discover(more=false){const request=++sourceSerial;sourceBusy=true;sourceError='';
 const mailbox=async()=>{try{const page=await invoke<{value:CalendarSource[];next:string|null}>('calendar_sources',{next:more?sourceNext:null});if(!alive||request!==sourceSerial)return;sources=[...new Map([...(more?sources:sources.filter(s=>s.kind)),...page.value.filter(s=>!s.isDefaultCalendar&&s.id!=='primary')].map(s=>[s.id,s])).values()];sourceNext=page.next;}catch{if(alive&&request===sourceSerial)sourceError='Mailbox calendar list unavailable. Refresh the list to retry.';}};
 const groups=async()=>{if(more)return;groupError='';try{const page=await invoke<{value:CalendarSource[]}>('calendar_group_sources');if(!alive||request!==sourceSerial)return;const ids=new Set(page.value.map(s=>s.id));for(const source of sources.filter(s=>s.kind==='group'&&!ids.has(s.id))){delete extra[source.id];eventRequests[source.id]=(eventRequests[source.id]??0)+1;if(selected?.calendarId===source.id)selected=null;}sources=[...sources.filter(s=>s.kind!=='group'),...page.value];}catch(e){if(alive&&request===sourceSerial){groupError=String(e);for(const s of sources.filter(s=>s.kind==='group')){extra[s.id]={rows:[],next:null,busy:false,error:groupError,range:day+'/'+days};eventRequests[s.id]=(eventRequests[s.id]??0)+1;if(selected?.calendarId===s.id)selected=null;}}}};
 try{await Promise.all([mailbox(),groups()]);if(alive&&request===sourceSerial)await loadVisible(true);}finally{if(alive&&request===sourceSerial)sourceBusy=false;}}
 async function restorePeople(){let ids:string[]=[];try{const saved=JSON.parse(localStorage.getItem('taut-calendar-people:'+ownId)||'[]');if(Array.isArray(saved)&&saved.length<=24)ids=[...new Set(saved.filter((id:unknown)=>typeof id==='string'&&/^[0-9a-f-]{36}$/i.test(id))) ] as string[];}catch{}
 for(const id of ids){try{const source=await invoke<CalendarSource>('calendar_person_source',{userId:id});if(!alive)return;sources=[...new Map([...sources,source].map(s=>[s.id,s])).values()];}catch(e){if(!alive)return;const key='person:'+id;sources=[...sources,{id:key,kind:'person',name:'Unavailable person’s calendar',isSharedWithMe:true}];extra[key]={rows:[],next:null,busy:false,error:String(e),range:day+'/'+days};}}
 }
 async function loadSource(id:string,more=false,force=false){if(id==='primary'||!sources.some(s=>s.id===id))return;const rangeKey=day+'/'+days;const old=extra[id];if(!more&&!force&&old?.range===rangeKey&&(old.busy||!old.error))return;const request=(eventRequests[id]??0)+1;eventRequests[id]=request;extra[id]={rows:more?old?.rows??[]:[],next:more?old?.next??null:null,busy:true,error:'',range:rangeKey};try{const page=await invoke<{value:CalendarEvent[];next:string|null}>('calendar_source_page',{calendarId:id,...calendarRange(day,days),next:more?old?.next:null});if(!alive||eventRequests[id]!==request||rangeKey!==day+'/'+days)return;extra[id]={rows:[...new Map([...(more?old?.rows??[]:[]),...page.value.map(e=>({...e,calendarId:id}))].map(e=>[e.id,e])).values()],next:page.next,busy:false,error:'',range:rangeKey};if(selected?.calendarId===id)selected=extra[id].rows.find(e=>e.id===selected?.id)??null;}catch(e){if(alive&&eventRequests[id]===request){extra[id]={rows:[],next:null,busy:false,error:String(e),range:rangeKey};if(selected?.calendarId===id)selected=null;}}}
 async function loadVisible(force=false){const ids=[...(focusId?[focusId]:enabled)].filter(id=>id!=='primary');for(let i=0;i<ids.length;i+=3)await Promise.all(ids.slice(i,i+3).map(id=>loadSource(id,false,force)));}
 function toggleSource(id:string){if(focusId)return;enabled=enabled.includes(id)?enabled.filter(value=>value!==id):enabled.length<12?[...enabled,id]:enabled;try{localStorage.setItem('taut-calendar-view:'+ownId,JSON.stringify(enabled));}catch{}if(selected&&!enabled.includes(selected.calendarId||'primary'))selected=null;void loadVisible();}
 async function focusSource(id:string){if(focusId===id){await returnToView();return;}if(!focusId)focusSnapshot={day,days,selected,scroll:agendaPane?.scrollTop??0,details:detailsOpen};focusId=id;selected=null;await loadVisible();}
 async function returnToView(){if(!focusSnapshot){focusId=null;return;}const saved=focusSnapshot;focusId=null;focusSnapshot=null;day=saved.day;days=saved.days;selected=saved.selected?.calendarId?(extra[saved.selected.calendarId]?.error?null:extra[saved.selected.calendarId]?.rows.find(e=>e.id===saved.selected?.id)??null):saved.selected;if(saved.details&&selected)onOpenDetails();else onCloseDetails();await tick();if(agendaPane)agendaPane.scrollTop=saved.scroll;}
 let managing=$state<{id:string;mode:'edit'|'cancel'}|null>(null);
 let composing=$state(false),canCreate=$state(false),creationNotice=$state('');
 let alive=true,serial=0;
 let responseRefresh=$state(0);
 let pendingEvent:CalendarEvent|null=null;
 async function openTarget(){if(!pendingEvent)return;const target=pendingEvent;const result=await invoke<{event:CalendarEvent}>('calendar_event',{eventId:target.id,messageId:null});if(!alive)return;selected=result.event;day=calendarAnchor(result.event,day);pendingEvent=null;onOpenDetails();}
 $effect(()=>onDetailsAvailable(composing||!managing&&!!selected));
 onDestroy(()=>{alive=false;serial++;sourceSerial++;onDetailsAvailable(false);});
 onMount(()=>{try{if(localStorage.getItem('taut-calendar-layout')==='agenda')layout='agenda';}catch{}try{const saved=JSON.parse(localStorage.getItem('taut-calendar-view:'+ownId)||'null');if(Array.isArray(saved)&&saved.length<=12&&saved.every(id=>typeof id==='string'&&id.length<=2048))enabled=[...new Set(saved)];}catch{}void (async()=>{try{if(isLive){permitted=await invoke<boolean>('calendar_permission');canCreate=await invoke<boolean>('calendar_response_permission');}if(alive&&permitted){if(initialEvent){pendingEvent=initialEvent;onNavigationHandled();await openTarget();}await load();await restorePeople();void discover();}}catch(e){if(alive)error=String(e);}finally{if(alive)checking=false;}})();});
 async function load(more=false){const request=++serial;busy=true;error='';try{await openTarget();if(!alive)return;if(!validCalendarDay(day))day=localDate(new Date());const range=calendarRange(day,days);const page=await invoke<{value:CalendarEvent[];next:string|null}>('calendar_page',{...range,next:more?next:null});if(!alive||request!==serial)return;rows=[...new Map([...(more?rows:[]),...page.value].map(e=>[e.id,e])).values()].sort((a,b)=>a.start.dateTime.localeCompare(b.start.dateTime));next=page.next;responseRefresh++;void loadVisible(!more);if(selected&&!selected.calendarId)selected=rows.find(e=>e.id===selected?.id)??selected;}catch(e){if(alive&&request===serial)error=String(e);}finally{if(alive&&request===serial)busy=false;}}
 function navigate(offset:number){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+offset);day=localDate(d);selected=null;rows=[];next=null;void load();}
 const rooms=$derived((selected?.attendees??[]).filter(attendee=>attendee.type==='resource'));
 const people=$derived((selected?.attendees??[]).filter(attendee=>attendee.type!=='resource'));
 const outlook=$derived(calendarLink(selected?.webLink));
</script>
<div class="calendar-workspace">
 {#if sidebarOpen}<aside class="date-panel"><div class="eyebrow">YOUR TIME. YOUR PACE.</div><h1>Calendar</h1><p>A little room for your day.</p><button disabled={!canCreate||!!managing||!!focusId} onclick={()=>{composing=true;onOpenDetails();}}>New meeting</button><label for="calendar-day">Starting date</label><input id="calendar-day" type="date" bind:value={day} disabled={busy||!permitted||!!managing||!!focusId} onchange={()=>{selected=null;rows=[];next=null;if(!day)day=localDate(new Date());void load();}}/><div class="range-options" aria-label="Calendar range">{#each [1,7,30] as count}<button class:chosen={days===count} disabled={busy||!permitted||!!managing||!!focusId} onclick={()=>{days=count;selected=null;rows=[];next=null;void load();}}>{count===1?'Day':count===7?'Week':'30 days'}</button>{/each}</div><button class="today" disabled={busy||!permitted||!!managing||!!focusId} onclick={()=>{day=localDate(new Date());navigate(0);}}>Today</button><CalendarPicker {sources} {enabled} {focusId} busy={sourceBusy} error={[sourceError,groupError].filter(Boolean).join(' ')} next={sourceNext} onToggle={toggleSource} onFocus={id=>void focusSource(id)} onRefresh={()=>void discover()} onMore={()=>void discover(true)} onRemove={removePerson} locked={composing||!!managing}/><CalendarPersonPicker {ownId} onAdd={addPerson} locked={composing||!!managing||!!focusId||sources.filter(s=>s.kind==='person').length>=24}/><div class="quiet-note">Your calendar, at your pace.<br/>Opening an event does not send a response.</div></aside>{/if}
 {#if managing}{#key managing.id+managing.mode}<MeetingEditor {ownId} eventId={managing.id} mode={managing.mode} onClose={()=>managing=null} onDone={result=>{managing=null;if(result.status==='updated'&&result.event){selected=result.event;day=calendarAnchor(result.event,day);creationNotice='Meeting updated. Attendee updates submitted; changed rooms await acceptance.';}else{selected=null;creationNotice='Cancellation submitted. Calendar and attendee updates may take a moment; no repeat will be sent.';}void load();}}/>{/key}{:else if composing}<MeetingComposer events={rows} {ownId} {detailsOpen} {onOpenDetails} {onCloseDetails} onClose={()=>composing=false} onCreated={(event,warning,submittedDay)=>{composing=false;selected=event;day=calendarAnchor(event,day,submittedDay);creationNotice=event.attendees?.some(a=>a.type==='resource')?'Meeting created. Invitations submitted; room booking awaits its response.':'Meeting created. Invitations submitted.';if(warning)creationNotice+=' '+warning;onOpenDetails();void load();}}/>{:else}<section class="agenda"><header><div><div class="eyebrow">ROOM TO FOCUS</div><h2>{new Date(day+'T12:00:00').toLocaleDateString([],{month:'long',year:'numeric'})}</h2></div><div class="agenda-tools"><div class="layout-options" role="group" aria-label="Calendar layout"><button aria-pressed={layout==='cards'} onclick={()=>void changeLayout('cards')}><LayoutGrid size={15}/>Cards</button><button aria-pressed={layout==='agenda'} onclick={()=>void changeLayout('agenda')}><List size={15}/>Agenda</button></div><div class="navigation"><button aria-label="Previous calendar range" disabled={busy||!permitted||!!managing||!!focusId} onclick={()=>navigate(-days)}><ChevronLeft size={18}/></button><button aria-label="Next calendar range" disabled={busy||!permitted||!!managing||!!focusId} onclick={()=>navigate(days)}><ChevronRight size={18}/></button><button aria-label="Refresh calendar" disabled={busy||!permitted||!!managing} onclick={()=>focusId&&focusId!=='primary'?void loadSource(focusId,false,true):void load()}><RefreshCw size={18}/></button></div></div></header>
 <div class="agenda-scroll" bind:this={agendaPane}>{#if focusId}<div class="focus-banner" role="status"><span>Temporary focus · <strong>{sourceName(focusId)}</strong></span><button onclick={()=>void returnToView()}>Back to my view</button></div>{/if}{#each activeSources.filter(id=>id!=='primary') as id}{#if !sources.some(s=>s.id===id)}<div class="source-error" role="status">A selected calendar is no longer available in the calendar list. Refresh the list or return to My view; no availability is inferred.</div>{/if}{#if extra[id]?.busy}<p class="coverage" role="status">Loading {sourceName(id)}…</p>{/if}{#if extra[id]?.error}<div class="source-error" role="alert"><strong>{sourceName(id)}</strong><p>{extra[id].error}</p><button onclick={()=>void loadSource(id,false,true)}>Retry this calendar</button></div>{/if}{/each}{#if creationNotice}<p role="status">{creationNotice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p><button onclick={()=>load()} disabled={busy||!permitted||!!managing||!!focusId}>Try again</button>{/if}
 {#if !isLive}<div class="empty"><CalendarDays size={48}/><h2>Your time, together.</h2><p>Sign in to view your calendar.</p><button onclick={onSignIn}>Sign in to Microsoft 365</button></div>{:else if checking}<p role="status">Connecting your calendar…</p>{:else if !permitted}<div class="empty"><CalendarDays size={48}/><h2>Connect your calendar</h2><p>Calendar needs Calendars.Read consent and a fresh sign-in. Chats and Mail remain available.</p></div>{:else}
 <p class="coverage">{day} · {days} {days===1?'day':'days'} · {visibleRows.length} events loaded{next?' · more available':''}</p>
 <div class="event-days" class:cards={layout==='cards'} class:compact-agenda={layout==='agenda'}>{#each eventDays as group(group.date)}<section class="event-day" aria-label={dayLabel(group.date)}><div class="day-label"><h3 class="day-heading">{dayLabel(group.date)}</h3><span>{group.events.length} {group.events.length===1?'event':'events'}</span></div><div class="day-events">{#each group.events as event(eventKey(event))}<button class="event" data-event-key={eventKey(event)} aria-pressed={!!selected&&eventKey(selected)===eventKey(event)} style:border-left-color={calendarTone(event.calendarId)} class:chosen={!!selected&&eventKey(selected)===eventKey(event)} class:cancelled={event.isCancelled} onclick={()=>{selected=event;onOpenDetails();}}><span class="calendar-origin" style:color={calendarTone(event.calendarId)}>{sourceName(event.calendarId)}</span><span class="event-time"><Clock size={14}/>{eventWhen(event)}</span><strong class="event-title">{event.subject||'Untitled event'}</strong><span class="event-place">{event.location?.displayName||event.organizer?.emailAddress?.name||'Calendar event'}</span><small class="event-status">{event.calendarId?(event.availabilityOnly?'Availability only':'View only in TAUT'):responseLabel(event)}</small>{#if meetingConflicts(event.calendarId?visibleRows.filter(e=>e.calendarId===event.calendarId):rows,eventDate(event.start)?.getTime()??NaN,eventDate(event.end)?.getTime()??NaN,event.id).length&&!event.isCancelled&&event.showAs!=='free'}<small class="event-overlap">Overlaps another event</small>{/if}</button>{/each}</div></section>{/each}</div>
 {#if !visibleRows.length&&!busy&&!error&&!activeSources.some(id=>id!=='primary'&&(extra[id]?.busy||extra[id]?.error))}<div class="empty"><CalendarDays size={44}/><h2>A little breathing room.</h2><p>No loaded events in this view. Check calendar visibility and any loading or access messages.</p></div>{/if}{#if busy}<p role="status">Loading events…</p>{/if}{#each activeSources.filter(id=>id!=='primary'&&extra[id]?.next) as id}<button disabled={extra[id].busy} onclick={()=>void loadSource(id,true)}>Load more · {sourceName(id)}</button>{/each}{#if next&&activeSources.includes('primary')}<button disabled={busy} onclick={()=>load(true)}>Load more events</button>{/if}{/if}</div></section>
 {/if}
 {#if !composing&&!managing&&detailsOpen&&selected}<aside class="event-details"><header><div><div class="eyebrow">EVENT DETAILS</div><h2>{selected.subject||'Untitled event'}</h2></div><button aria-label="Close event details" onclick={onCloseDetails}><X size={18}/></button></header><div class="detail-scroll"><div class="calendar-attribution" style:border-left-color={calendarTone(selected.calendarId)}><strong>{sourceName(selected.calendarId)}</strong>{#if selected.calendarId}<small>{sources.find(s=>s.id===selected?.calendarId)?.owner?.name||sources.find(s=>s.id===selected?.calendarId)?.owner?.address||'Owner unavailable'} · View only in TAUT</small>{/if}</div><TeamsMeeting event={selected}/>{#if ['seriesMaster','occurrence','exception'].includes(selected.type??'')}<p class="coverage">Recurring meeting. Manage the series in Outlook.</p>{/if}{#if !selected.calendarId&&canCreate&&canManageMeeting(selected)}<div class="organizer-actions"><button onclick={()=>{if(selected)managing={id:selected.id,mode:'edit'};}}>Edit meeting</button><button onclick={()=>{if(selected)managing={id:selected.id,mode:'cancel'};}}>Cancel meeting</button></div>{/if}{#if rooms.length}<section class="room-booking" aria-label="Room booking"><h3><MapPin size={17}/>Room booking</h3>{#each rooms as room}<div class="room-status" class:declined={room.status?.response==='declined'}><strong class="room-name">{room.emailAddress?.name||room.emailAddress?.address||'Room'}</strong><strong class="room-outcome">{room.status?.response==='declined'?'Room declined':room.status?.response==='accepted'?'Room accepted':!room.status?.response||['none','notResponded'].includes(room.status.response)?'Requested — awaiting room response':attendeeResponseLabel(room.status.response)}</strong>{#if room.status?.response==='declined'}<p>This room is not booked for this meeting.</p>{/if}</div>{/each}</section>{/if}{#if !selected.calendarId}{#key selected.id}<MeetingResponse {ownId} refreshKey={responseRefresh} eventId={selected.id} onUpdated={event=>{selected=event;rows=rows.map(row=>row.id===event.id?event:row);}}/>{/key}{/if}<h3><Clock size={16}/>When</h3><p>{eventDay(selected)}<br/>{eventWhen(selected)}</p><small>Timed events shown in {Intl.DateTimeFormat().resolvedOptions().timeZone}. All-day events keep their calendar date.</small><h3><MapPin size={16}/>Where</h3><p>{selected.location?.displayName||'No location provided'}</p><h3>Organizer</h3><p>{selected.organizer?.emailAddress?.name}<br/>{selected.organizer?.emailAddress?.address}</p>{#if selected.bodyPreview}<h3>About this event</h3><p class="description">{selected.bodyPreview}</p><small>Description preview</small>{/if}<h3><Users size={16}/>Attendees · {people.length}</h3>{#each people as attendee}<div class="attendee"><strong>{attendee.emailAddress?.name||attendee.emailAddress?.address||'Attendee'}</strong><small>{calendarAttendeeLabel(selected,attendee)}</small></div>{/each}{#if outlook}<button class="outlook" onclick={()=>{if(outlook)void openUrl(outlook).catch(()=>error='Outlook could not be opened.');}}>Open in Outlook ↗</button>{/if}</div></aside>{/if}
</div>
<style>
.agenda{container-type:inline-size}.agenda-tools{display:flex;align-items:center;justify-content:flex-end;gap:16px;flex-wrap:wrap}.layout-options{display:flex;padding:3px;border:1px solid var(--border);border-radius:10px;background:var(--surface-raised);gap:3px}.layout-options button{display:inline-flex;align-items:center;gap:6px;border-color:transparent;padding:8px 10px;font-size:12px;background:transparent}.layout-options button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent-border);color:var(--accent)}.day-label{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:24px 0 12px}.day-label .day-heading{margin:0;letter-spacing:.3px;font-size:13px;color:var(--text-primary)}.day-label>span{color:var(--text-secondary);font-size:11px}.day-events{display:grid;gap:12px}.day-events .event{margin:0;min-width:0;box-sizing:border-box;overflow-wrap:anywhere}.cards .event{padding:18px;align-content:start;min-height:185px;grid-template-rows:auto auto 1fr auto auto;gap:10px;border-radius:12px}.cards .event-title{font-size:17px;line-height:1.4}.cards .event-time{font-weight:600}.cards .event-place{line-height:1.5}.event-overlap{color:var(--accent)!important}.compact-agenda .day-events{gap:7px}.compact-agenda .event{padding:12px 16px;gap:3px 16px;grid-template-columns:145px minmax(0,1fr) 150px;grid-template-areas:'time title status' 'time place status' 'time origin overlap';align-items:center}.compact-agenda .event-time{grid-area:time;line-height:1.7}.compact-agenda .event-title{grid-area:title;font-size:14px;line-height:1.5}.compact-agenda .event-place{grid-area:place;font-size:11px!important}.compact-agenda .calendar-origin{grid-area:origin}.compact-agenda .event-status{grid-area:status;text-align:right}.compact-agenda .event-overlap{grid-area:overlap;text-align:right;font-size:10px}.event-days .event:hover:not(:disabled){background:var(--accent-soft)}
@container (min-width:600px){.cards .day-events{grid-template-columns:repeat(2,minmax(0,1fr))}}
@container (min-width:960px){.cards .day-events{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container (max-width:599px){.compact-agenda .event{grid-template-columns:1fr;grid-template-areas:'time' 'title' 'place' 'origin' 'status' 'overlap';gap:6px}.compact-agenda .event-status,.compact-agenda .event-overlap{text-align:left}.agenda>header{flex-wrap:wrap}.agenda-tools{justify-content:flex-start;gap:10px}}

.focus-banner{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;border:1px solid var(--accent-border);background:var(--accent-soft);border-radius:9px;padding:14px;margin-bottom:20px;font-size:12px}.calendar-origin{font-size:10px!important}.calendar-attribution{border-left:3px solid var(--accent);padding-left:12px;margin-bottom:20px;font-size:13px}.calendar-attribution small{display:block;margin-top:5px}.source-error{border:1px solid var(--border);padding:12px;border-radius:8px;margin-bottom:12px;font-size:12px}.date-panel{overflow:auto;min-height:0}

.organizer-actions{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.organizer-actions button{font-size:12px;color:var(--accent)}

.room-booking{margin:0 0 20px}.detail-scroll .room-booking h3{margin:0 0 12px;font-size:13px;color:var(--text-secondary)}.room-status{padding:16px;border:1px solid var(--border-strong);border-radius:10px;margin-top:10px;background:var(--surface-raised);overflow-wrap:anywhere}.room-name{display:block;font-size:14px;line-height:1.5}.room-outcome{display:block;font-size:16px;line-height:1.5;margin-top:8px}.room-status.declined{background:var(--error-surface);border-color:var(--error-border);border-left-width:4px}.room-status.declined .room-outcome{color:var(--error)}.detail-scroll .room-status p{margin:8px 0 0;font-size:12px;color:var(--text-primary)}

.calendar-workspace{display:flex;flex:1;height:100%;min-height:0;min-width:0;color:var(--text-primary)}button,input{font:inherit;color:inherit}button{cursor:pointer;border:1px solid var(--border);background:var(--surface-panel);border-radius:9px;padding:10px 14px}button:disabled{opacity:.45;cursor:default}button:hover:not(:disabled){border-color:var(--accent)}.eyebrow{color:var(--accent);font-size:10px;letter-spacing:2px;font-weight:700}.date-panel{width:280px;flex:none;padding:32px 24px;background:var(--surface-panel);border-right:1px solid var(--border);display:flex;flex-direction:column;gap:18px}.date-panel h1{font-size:30px;margin:0}.date-panel p,.quiet-note,small,.coverage{color:var(--text-secondary);line-height:1.7}.date-panel label{font-size:12px;margin-top:24px}.date-panel input{width:100%;box-sizing:border-box;padding:12px;border:1px solid var(--border-strong);border-radius:9px;background:var(--surface-raised)}.range-options{display:flex;gap:6px}.range-options button{flex:1;padding:10px 5px}.chosen{border-color:var(--accent)!important;background:var(--accent-soft)!important}.quiet-note{margin-top:auto;font-size:11px}.agenda{flex:1;min-width:0;display:flex;flex-direction:column}.agenda>header,.event-details>header{padding:28px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border);background:var(--surface-panel)}h2{margin:10px 0 0;font-size:23px}.navigation{display:flex;gap:7px}.navigation button{display:grid;place-items:center;padding:10px}.agenda-scroll,.detail-scroll{flex:1;overflow:auto;min-height:0;padding:26px}.coverage{font-size:11px;margin:0 0 28px}.day-heading{font-size:12px;letter-spacing:1px;color:var(--text-secondary);margin:25px 0 12px}.event{width:100%;text-align:left;display:grid;gap:9px;padding:20px 24px;margin-bottom:12px;border-left:3px solid var(--accent);background:var(--surface-panel)}.event strong{font-size:17px}.event>span:not(.event-time){font-size:12px;color:var(--text-secondary)}.event-time{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--accent)}.event small{font-size:11px}.cancelled strong{text-decoration:line-through}.empty{padding:60px 20px;text-align:center;color:var(--text-secondary)}.empty :global(svg){color:var(--accent)}.empty p{line-height:1.8}.event-details{width:350px;max-width:40%;flex:none;display:flex;flex-direction:column;background:var(--surface-panel);border-left:1px solid var(--border)}.event-details h2{font-size:19px;line-height:1.5}.detail-scroll h3{display:flex;gap:9px;align-items:center;font-size:12px;margin-top:28px}.detail-scroll p{line-height:1.8;font-size:13px;overflow-wrap:anywhere}.detail-scroll small{font-size:11px}.description{white-space:pre-wrap}.attendee{display:grid;gap:5px;padding:12px 0;border-bottom:1px solid var(--border);font-size:12px}.outlook{margin-top:24px;color:var(--accent)}.error{color:var(--danger-text,#e88d7d);line-height:1.7}@media(max-width:1000px){.date-panel{width:210px;padding:24px 16px}.event-details{width:290px}}button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
</style>
